sys_ux_data_broker_transform.script:
(function() {
    // Log input data for debugging
    gs.info('Input Data: ' + JSON.stringify(data));

    if (!data) {
        gs.error('No input data found');
        return;
    }

    // Define the output object
    var kpiValues = { 'buttonsvis': [] };

    // Define the buttons data array
    var buttonsData = [
        { "id": "button1", "label": "8.33%", "value": 8.33 },
        { "id": "button2", "label": "12.5%", "value": 12.5 },
        { "id": "button3", "label": "16.67%", "value": 16.67 },
        { "id": "button4", "label": "20%", "value": 20 },
        { "id": "button5", "label": "25%", "value": 25 },
        { "id": "button6", "label": "33.33%", "value": 33.33 }
    ];

    // Log the buttonsData to make sure it’s correctly defined
    gs.info('Buttons Data: ' + JSON.stringify(buttonsData));

    // Map the buttonsData to the desired output format
    kpiValues.buttonsvis = buttonsData.map(function(button) {
        return {
            id: button.id,
            label: button.label,
            value: button.value
        };
    });

    // Log the transformed data
    gs.info('Transformed Data: ' + JSON.stringify(kpiValues));

    // Return the transformed data
    return kpiValues;
})();
